import {createRequire} from 'node:module';
import path from 'node:path';
const [root,product]=process.argv.slice(2);
const site=path.join(root,product,'docs');
const require=createRequire(path.join(site,'package.json'));
const ts=require('typescript');
const options={noEmit:true,strict:true,skipLibCheck:true,esModuleInterop:true,target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.ESNext,moduleResolution:ts.ModuleResolutionKind.Bundler,types:['node'],typeRoots:[path.join(site,'node_modules/@types')]};
const host=ts.createCompilerHost(options);
host.resolveModuleNames=(names,containingFile)=>names.map(name=>{
 const anchor=!name.startsWith('.') && containingFile.startsWith(path.join(root,'scripts/docs-site'))?path.join(site,'src/probe.ts'):containingFile;
 return ts.resolveModuleName(name,anchor,options,host).resolvedModule;
});
const program=ts.createProgram([path.join(root,'scripts/docs-site/page.ts'),path.join(root,'scripts/docs-site/runtime.ts')],options,host);
const diagnostics=ts.getPreEmitDiagnostics(program);
for(const d of diagnostics)console.log(ts.flattenDiagnosticMessageText(d.messageText,'\n'));
console.log(`Shared helper diagnostics: ${diagnostics.length}`);
process.exitCode=diagnostics.length?1:0;

import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {createRequire} from 'node:module';
import {pathToFileURL} from 'node:url';
import path from 'node:path';
const site=process.argv[2];
const require=createRequire(path.join(site,'package.json'));
const {unflatten}=await import(pathToFileURL(require.resolve('devalue')));
const {Server}=await import(pathToFileURL(path.join(site,'.svelte-kit/output/server/index.js')));
const {manifest}=await import(pathToFileURL(path.join(site,'.svelte-kit/output/server/manifest.js')));
const server=new Server(manifest);await server.init({env:{}});
async function request(route){
 const r=await server.respond(new Request(`http://localhost${route}`),{getClientAddress:()=> '127.0.0.1'});
 assert.equal(r.status,200,route);return r.text();
}
const summaries=[];
for(const route of ['/','/docs/getting-started']){
 const html=await request(route);
 const titles=[...html.matchAll(/<title[^>]*>([\s\S]*?)<\/title>/g)].map(m=>m[1].replace(/<!--[\s\S]*?-->/g,''));
 assert.equal(titles.length,1);assert.notEqual(titles[0],'BotFn docs');summaries.push({route,titles});
}
const data=JSON.parse(await request('/docs/getting-started/__data.json'));
const page=unflatten(data.nodes.at(-1).data);assert.deepEqual(page.routeEntry,{kind:'page'});assert.ok(page.compiled);
for(const file of ['llms.txt','llms-full.txt']){
 const asset=readFileSync(path.join(site,'.svelte-kit/output/prerendered/pages/docs',file),'utf8');
 assert.equal(asset,readFileSync(path.join(site,'static',file),'utf8'));
 assert.match(asset,/https:\/\/github\.com\/21nCo\/super-functions\/blob\/dev\/botfn\/docs\/content\/docs/);
}
const search=JSON.parse(await request('/docs/search.json'));assert.equal(search.documents.length,12);
console.log(JSON.stringify({summaries,pageRouteEntry:page.routeEntry,prerenderedLlm:'byte-identical /docs assets with source links',searchDocuments:12}));

import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
const root = '/Users/serro/orca/workspaces/superfunctions/docs-pr-211-review-20260930';
const head = '6bf3dcc81ba3cb3f3b6524f21c343dc59a7babeb';
const run = (cmd,args,cwd=root,env={}) => execFileSync(cmd,args,{cwd,encoding:'utf8',env:{...process.env,...env},maxBuffer:16*1024*1024});
const read = file => fs.readFileSync(path.join(root,file),'utf8');
const old = file => run('git',['show',`${head}:${file}`]);
const tmp = fs.mkdtempSync(path.join(os.tmpdir(),'sf-pr211-verify-'));
const put = (base,file,text,mode) => { const p=path.join(base,file); fs.mkdirSync(path.dirname(p),{recursive:true}); fs.writeFileSync(p,text, mode ? {mode} : undefined); };
try {
  // Published consumer text must distinguish ordinary Next.js from pipeline staging.
  const doc='datafn/docs/content/docs/ai-resources/index.mdx';
  assert.match(old(doc), /same URLs work against your own deployment/);
  assert.doesNotMatch(old(doc), /standard Next\.js self-hosted deployment/);
  assert.match(read(doc), /standard Next\.js self-hosted deployment serves raw Markdown at `\/api\/docs\/raw\/<path>`/);
  assert.match(read(doc), /`\/llms\.txt` and `\/llms-full\.txt`/);
  assert.match(read(doc), /build flag alone does not relocate the LLM artifacts/);
  const route=read('datafn/docs/app/docs/[[...slug]]/page.tsx');
  assert.match(route, /CLOUDFLARE_DOCS_DEPLOY === "1"\s*\? "\/docs\/api\/docs\/raw"\s*: "\/api\/docs\/raw"/);
  const generation = () => run(process.execPath,['datafn/docs/scripts/generate-llms.mjs'],root,{NEXT_PUBLIC_SITE_URL:'https://datafn.dev'});
  console.log(generation().trim());
  const outputs=['datafn/docs/public/llms.txt','datafn/docs/public/llms-full.txt'];
  const first=outputs.map(read); generation(); assert.deepEqual(outputs.map(read),first);
  assert.ok(first[1].includes(read(doc).split('\n---\n')[1].trim()));
  for (const text of first) assert.doesNotMatch(text, /https:\/\/datafn\.(?:com|21n\.co)/);
  console.log('PASS: old-head docs contract distinguished; corrected corpus deterministic');

  // Execute the unchanged deployment CLI. External commands are guarded stubs;
  // acceptance inspects the actual staged filesystem and passed environment.
  const deploy=path.join(tmp,'deployment');
  for (const f of ['scripts/cloudflare-docs/config.mjs','scripts/cloudflare-docs/deploy.mjs','datafn/docs/package.json']) put(deploy,f,read(f));
  for (const [f,text] of Object.entries({'docs/index.html':'fixture index','llms.txt':'fixture index inventory','llms-full.txt':'fixture full inventory','api/docs/raw/dfql/queries.mdx':'fixture raw markdown','_next/static/test.js':'fixture asset'})) put(deploy,`datafn/docs/out/${f}`,text);
  put(deploy,'node_modules/.bin/wrangler','#!/bin/sh\ncase " $* " in *" --dry-run "*) exit 0;; *) exit 99;; esac\n',0o755);
  put(deploy,'bin/npx','#!/bin/sh\nprintf "%s\\n" "$CLOUDFLARE_DOCS_DEPLOY" "$CLOUDFLARE_DOCS_ASSETS_ORIGIN" "$NEXT_PUBLIC_SITE_URL" "$*" > "$BUILD_CAPTURE"\n',0o755);
  for(const [mode,host] of [['live','datafn.dev'],['dev','dev.datafn.dev']]) {
    const capture=path.join(tmp,`${mode}.capture`);
    run(process.execPath,['scripts/cloudflare-docs/deploy.mjs',mode,'--products=datafn','--dry-run'],deploy,{PATH:`${path.join(deploy,'bin')}:${process.env.PATH}`,BUILD_CAPTURE:capture});
    const stage=path.join(deploy,'datafn/docs/.cloudflare-docs-assets');
    for(const f of ['llms.txt','llms-full.txt','api/docs/raw/dfql/queries.mdx']) assert.equal(fs.readFileSync(path.join(stage,'docs',f),'utf8'), fs.readFileSync(path.join(deploy,'datafn/docs/out',f),'utf8'));
    assert.equal(fs.readFileSync(capture,'utf8').split('\n')[0],'1');
    assert.equal(fs.readFileSync(capture,'utf8').split('\n')[1],`https://${host}/docs`);
    assert.equal(fs.readFileSync(capture,'utf8').split('\n')[2],`https://${host}`);
  }
  console.log('PASS: dev/live CLI environment and byte-identical staged raw/LLM files; external commands stubbed, not deployed');

  // Turbo must enforce runtime workspace build edges, not rely on a lucky race.
  const files=run('git',['ls-files','--','package.json','**/package.json','package-lock.json','turbo.json']).trim().split('\n');
  const authManifest='authfn/docs/package.json';
  const plans={};
  for (const version of ['old','new']) {
    const base=path.join(tmp,version);
    for (const f of files) put(base,f,(version==='old' && [authManifest,'package-lock.json'].includes(f)) ? old(f) : read(f));
    const plan=JSON.parse(run(path.join(root,'node_modules/.bin/turbo'),['run','build','--filter=@authfn/docs','--dry=json'],base));
    plans[version]=plan.tasks.find(t=>t.taskId==='@authfn/docs#build').dependencies;
  }
  for(const task of ['@superfunctions/observability#build','@superfunctions/oauth-flow#build']) {
    assert.ok(!plans.old.includes(task),`old plan unexpectedly includes ${task}`);
    assert.ok(plans.new.includes(task),`new plan missing ${task}`);
  }
  const deps=JSON.parse(read(authManifest)).devDependencies;
  const locked=JSON.parse(read('package-lock.json')).packages['authfn/docs'].devDependencies;
  for(const name of ['@superfunctions/observability','@superfunctions/oauth-flow']) assert.equal(locked[name],deps[name]);
  console.log('PASS: old missing build edges distinguished from repaired Turbo graph; lock agrees');
  console.log(JSON.stringify(plans));
  run('git',['diff','--check']);
} finally { fs.rmSync(tmp,{recursive:true,force:true}); }

  const cloudflareOutputDir = path.join(docsDir, ".svelte-kit", "cloudflare");
  const workerEntry = path.join(cloudflareOutputDir, "_worker.js");
  assertFile(workerEntry, `SvelteKit Cloudflare build did not produce ${path.relative(repoRoot, workerEntry)}`);
  fs.writeFileSync(path.join(cloudflareOutputDir, ".assetsignore"), "_worker.js\n");

  const wranglerConfig = writeWranglerConfig(docsDir, {
    name,
    main: ".svelte-kit/cloudflare/_worker.js",
    assetsDirectory: ".svelte-kit/cloudflare",
    compatibilityFlags: ["nodejs_compat"],
  });
  runWranglerDeploy(docsDir, wranglerConfig, name);
}

function writeWranglerConfig(docsDir, options) {
  const configPath = path.join(docsDir, ".cloudflare-docs-wrangler.jsonc");
  const config = {
    name: options.name,
    compatibility_date: "2026-05-18",
    workers_dev: true,
    observability: {
      enabled: true,
    },
    assets: {
      directory: options.assetsDirectory,
    },
  };
  if (options.main) config.main = options.main;
  if (options.compatibilityFlags) config.compatibility_flags = options.compatibilityFlags;

  fs.writeFileSync(configPath, `${JSON.stringify(config, null, 2)}\n`);
  return configPath;
}

function runWranglerDeploy(cwd, configPath, name) {
  run(resolveWranglerBin(), [
    "deploy",
    "--config",
    configPath,
    ...(dryRun ? ["--dry-run"] : []),
  ], { cwd });
}

function copyDir(from, to) {
  fs.mkdirSync(to, { recursive: true });
  fs.cpSync(from, to, { recursive: true });
}

function assertFile(filePath, message) {
  if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
    throw new Error(message);
  }
}

function resolveWranglerBin() {
  const extension = process.platform === "win32" ? ".cmd" : "";
  const localBin = path.join(repoRoot, "node_modules", ".bin", `wrangler${extension}`);
  if (fs.existsSync(localBin)) return localBin;
  return "wrangler";
}

function run(command, args, options = {}) {
  console.log(`\n$ ${command} ${args.join(" ")}`);
  const result = spawnSync(command, args, {
    cwd: options.cwd ?? repoRoot,
    stdio: "inherit",
    env: {
      ...process.env,
      ...(options.env ?? {}),
    },
    shell: process.platform === "win32",
  });
  if (result.status !== 0) {
    process.exit(result.status ?? 1);
  }
}

function getArgValue(name) {
  return process.argv.find((arg) => arg.startsWith(`--${name}=`))?.split("=").slice(1).join("=");
}

