import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import {createRequire} from 'node:module';
import {pathToFileURL} from 'node:url';
const root='/Users/serro/orca/workspaces/superfunctions/docs-pr-206-review-20260930';
const site=path.join(root,'filefn/docs');const require=createRequire(path.join(site,'package.json'));
const rootRequire=createRequire(path.join(root,'package.json'));
const {chromium}=rootRequire('@playwright/test');
const {createServer}=await import(pathToFileURL(require.resolve('vite')));
const {svelte}=await import(pathToFileURL(require.resolve('@sveltejs/vite-plugin-svelte')));
const base=fs.mkdtempSync(path.join(os.tmpdir(),'sf214-search-'));let server,browser;
try {
 fs.symlinkSync(path.join(site,'node_modules'),path.join(base,'node_modules'),'dir');
 fs.writeFileSync(path.join(base,'package.json'),JSON.stringify({type:'module'}));
 fs.writeFileSync(path.join(base,'index.html'),'<div id="app"></div><script type="module" src="/main.js"></script>');
 fs.writeFileSync(path.join(base,'main.js'),`import {mount} from 'svelte';import Search from '${root}/scripts/docs-site/Search.svelte';mount(Search,{target:document.querySelector('#app')});`);
 fs.writeFileSync(path.join(base,'runtime.js'),`window.requests=[];export function createDocsSearchRuntime(){return {query(input){return new Promise((resolve,reject)=>window.requests.push({input,resolve,reject}));}};}`);
 server=await createServer({root:base,configFile:false,plugins:[svelte()],resolve:{dedupe:['svelte'],alias:[{find:'@docsfn/core/search-runtime',replacement:path.join(base,'runtime.js')}]},server:{host:'127.0.0.1',port:0,fs:{allow:[base,root]}}});await server.listen();
 const port=server.httpServer.address().port;
 browser=await chromium.launch({headless:true});const page=await browser.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto(`http://127.0.0.1:${port}`);await page.getByRole('button',{name:/^Search/}).click();
 const input=page.getByRole('searchbox');const links=page.locator('dialog li a');
 const complete=async(count,index=0)=>page.evaluate(({count,index})=>{
  const r=window.requests.splice(index,1)[0];r.resolve(Array.from({length:count},(_,i)=>({id:`${r.input.query}-${i}`,path:`/docs/${i}`,title:`${r.input.query} result ${i}`})));
 },{count,index});
 const waitRequests=async(n)=>page.waitForFunction(n=>window.requests.length===n,n);
 await input.fill('alpha');await waitRequests(1);await complete(11);await page.waitForFunction(()=>document.querySelectorAll('dialog li').length===10);
 let more=page.getByRole('button',{name:'Show more results'});await more.focus();await more.click();await waitRequests(1);
 assert.equal(await links.count(),10,'pagination must retain prior results while pending');assert.equal(await more.evaluate(el=>el===document.activeElement),true,'pending pagination must retain focused button');
 await complete(21);await page.waitForFunction(()=>document.querySelectorAll('dialog li').length===20);
 await more.click();await waitRequests(1);assert.equal(await links.count(),20);await complete(24);await page.waitForFunction(()=>document.querySelectorAll('dialog li').length===24);
 assert.equal(await page.getByRole('button',{name:'Show more results'}).count(),0);assert.equal(await page.evaluate(()=>document.activeElement?.textContent),'alpha result 20','final page moves focus to newly exposed result');
 // A new query clears stale results; a superseded response cannot reclaim ownership.
 await input.fill('old');await waitRequests(1);assert.equal(await links.count(),0);await input.fill('new');await waitRequests(2);await complete(3,1);await page.waitForFunction(()=>document.querySelectorAll('dialog li').length===3);await complete(8,0);await page.waitForTimeout(30);assert.match(await links.first().innerText(),/^new /);
 // Empty query invalidates requests without accepting a delayed result.
 await input.fill('cleared');await waitRequests(1);await input.fill('');assert.equal(await links.count(),0);await complete(7);await page.waitForTimeout(30);assert.equal(await links.count(),0);
 // Pagination failures leave prior results and a usable retry control.
 await input.fill('retry');await waitRequests(1);await complete(11);await page.waitForFunction(()=>document.querySelectorAll('dialog li').length===10);more=page.getByRole('button',{name:'Show more results'});await more.click();await waitRequests(1);await page.evaluate(()=>window.requests.shift().reject(new Error('fixture failure')));await page.getByRole('alert').waitFor();assert.equal(await links.count(),10);assert.equal(await more.count(),1);
 await page.keyboard.press('Escape');assert.equal(await page.locator('dialog').evaluate(el=>el.open),false);assert.deepEqual(errors,[]);
 console.log('PASS actual Chromium/Svelte component: pending/final-page focus, preserved lists, query changes, stale/cleared requests, error/retry control, Escape; search transport mocked');
} finally {await browser?.close();await server?.close();fs.rmSync(base,{recursive:true,force:true});}

