import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
/**
 * Resolve DocsFn from the consumer site so each site's published package pin is honored.
 * @param {string} cwd
 * @param {{buildManifest: Function, loadDocsConfig: Function, FsContentProvider: new (options: object) => object}} dependencies
 */
export async function loadLlmsSiteSource(cwd, dependencies) {
  const { buildManifest, loadDocsConfig, FsContentProvider } = dependencies;
  const config = await loadDocsConfig({ cwd });
  const provider = new FsContentProvider({
    root: config.content.root || cwd,
    docsDir: config.content.docsDir,
    pagesDir: config.content.pagesDir,
    blogDir: config.content.blogDir,
    apiDir: config.content.apiDir,
    assetsDir: config.content.assetsDir,
  });
  const manifest = await buildManifest(provider, config);
  return { config, manifest };
}

/** @param {string} cwd
 * @param {Parameters<typeof loadLlmsSiteSource>[1] & { buildLlmsTxtArtifacts: Function }} dependencies
 */
export async function buildLlmsSiteArtifacts(cwd, dependencies, options = {}) {
  const { config, manifest } = await loadLlmsSiteSource(cwd, dependencies);
  const { buildLlmsTxtArtifacts } = dependencies;
  const canonicalUrl = options.canonicalUrl ?? config.site?.canonicalUrl;
  const artifacts = buildLlmsTxtArtifacts(manifest, {
    canonicalUrl,
    includeBlog: false,
  });
  return { artifacts, config, manifest, canonicalUrl };
}

/**
 * Keep LLM indexes navigable before a public documentation host is assigned.
 * @param {string} text
 * @param {import("@docsfn/core").DocsManifest} manifest
 * @param {string} product
 * @param {string | undefined} canonicalUrl
 */
export function withSourceLinks(text, manifest, product, canonicalUrl) {
  if (canonicalUrl) return text;
  const sources = new Map(Object.values(manifest.pages)
    .filter((page) => page.id.startsWith("docs:"))
    .map((page) => [page.path, page.id.slice("docs:".length)]));
  return text.replace(/\]\((\/docs[^\s)]*)\)/g, (match, href) => {
    const url = new URL(href, "https://docs.invalid");
    const source = sources.get(url.pathname);
    if (!source) return match;
    const path = source.split("/").map(encodeURIComponent).join("/");
    return `](https://github.com/21nCo/super-functions/blob/dev/${product}/docs/content/docs/${path}${url.hash})`;
  });
}

/**
 * --check compares without modifying tracked artifacts.
 * @param {string} directory
 * @param {{llmsTxt: string, llmsFullTxt: string}} artifacts
 * @param {boolean} check
 */
export function writeLlmsArtifacts(directory, artifacts, check = process.argv.includes("--check")) {
  const files = { "llms.txt": artifacts.llmsTxt, "llms-full.txt": artifacts.llmsFullTxt };
  if (!check) mkdirSync(directory, { recursive: true });
  for (const [name, body] of Object.entries(files)) {
    const target = resolve(directory, name);
    if (check) {
      let actual;
      try { actual = readFileSync(target, "utf8"); } catch { /* Report missing files as stale. */ }
      if (actual !== body) throw new Error(`${name} is stale; run npm run generate:llms`);
    } else writeFileSync(target, body, "utf8");
  }
  console.log(check ? "LLM artifacts are current" : "Updated LLM artifacts");
}

---
title: HTTP routes
description: Mount model and trace endpoints with trusted authentication.
---

`createLangFnRouter(lang, options)` uses `@superfunctions/http` and defaults to a one MiB JSON body limit. The route set includes `GET /health`, `POST /complete`, `POST /chat`, `POST /stream`, `POST /embed`, `GET /traces`, and `POST /feedback`. The host mounts the router and supplies authentication and rate-limit providers appropriate to its deployment.

Trace listing and feedback require an authenticated actor. Their stored and queried scope comes from trusted session metadata, not request-supplied tenant or user values. Custom trace stores serving scoped HTTP access must advertise `supportsScope: true`, apply both tenant and user predicates before pagination, and implement scoped `findOne` for feedback ownership. Historical unowned traces do not appear in HTTP results.

HTTP provider errors omit upstream response bodies and metadata. The built-in `POST /stream` SSE route cancels model work when the request signal aborts; this requires a host bridge that propagates disconnects and streams response chunks. The current `@superfunctions/http-express` adapter buffers responses and does not provide that behavior. See the [source router](https://github.com/21nCo/super-functions/blob/dev/langfn/typescript/src/http/routes.ts) and [release gate](/docs/reference/release-gate) for exact input and scope rules.

## Mount an authenticated Node 20.16+ server

Run this example in the repository checkout after building the local `langfn` workspace as described in the [TypeScript package guide](/docs/reference/typescript). The source changes documented here are not yet available from the registry.

```sh
npm install express
npm install --save-dev tsx
```

This local single-user example requires `LANGFN_DEMO_TOKEN`, `OPENAI_API_KEY`, and `OPENAI_MODEL` in the server environment. Save it as `server.ts` and run `npx tsx server.ts`:

```ts
import express from "express";
import { createHash, timingSafeEqual } from "node:crypto";
import { LangFn } from "langfn";
import { OpenAIChatModel } from "langfn/models";
import { createLangFnRouter } from "langfn/http";
import { langFnHandler } from "./langfn-express";

const token = process.env.LANGFN_DEMO_TOKEN;
if (!token || !process.env.OPENAI_API_KEY || !process.env.OPENAI_MODEL) {
  throw new Error("Set the demo token, provider key, and model");
}
const tokenDigest = createHash("sha256").update(token).digest();
const lang = new LangFn({ model: new OpenAIChatModel({
  apiKey: process.env.OPENAI_API_KEY, model: process.env.OPENAI_MODEL,
}) });
const router = createLangFnRouter(lang, {
  auth: {
    validateBearerToken(value) {
      const suppliedDigest = createHash("sha256").update(value).digest();
      return timingSafeEqual(suppliedDigest, tokenDigest) ? {
        id: "local-session", type: "bearer",
        subject: { actorId: "local-user", actorType: "user", tenantId: "local" },
      } : null;
    },
  },
  maxBodyBytes: 1024 * 1024,
});
const app = express();
// Keep body parsers off this mount; LangFn enforces its JSON limit.
app.use("/api/langfn", langFnHandler(router));
app.listen(3020);
```

```sh
curl http://localhost:3020/api/langfn/complete \
  -H "Authorization: Bearer $LANGFN_DEMO_TOKEN" \
  -H 'Content-Type: application/json' \
  -d '{"prompt":"Describe optimistic concurrency in one sentence."}'
```

Read the response envelope and check `ok` before using its data. Invalid credentials return an authentication error; oversized requests are rejected. In production, replace the demo token check with the host's session provider and configure the rate-limit provider. Keep model credentials server-side and configure scoped trace storage before enabling trace/feedback features. The mount prefix belongs to the HTTP adapter; the LangFn router's routes remain `/complete`, `/chat`, and so on.

## Streaming Express bridge

Save this as `langfn-express.ts` next to `server.ts`. It pipes the Web response with backpressure and aborts the request signal on disconnect, including during `/stream`. It does not buffer an entire SSE response before sending it.

```ts
import type { RequestHandler } from "express";
import { Readable } from "node:stream";
import { pipeline } from "node:stream/promises";
import type { ReadableStream as NodeReadableStream } from "node:stream/web";

type WebRouter = { handle(request: Request): Promise<Response | null> };

export function langFnHandler(router: WebRouter): RequestHandler {
  return (req, res, next) => {
    const controller = new AbortController();
    const abort = () => { if (!res.writableEnded) controller.abort(); };
    req.once("aborted", abort);
    res.once("close", abort);
    void (async () => {
      const headers = new Headers();
      for (let i = 0; i < req.rawHeaders.length; i += 2) {
        headers.append(req.rawHeaders[i], req.rawHeaders[i + 1]);
      }
      // Express strips the mount prefix from req.url while this mounted handler runs.
      const url = new URL(req.url, `${req.protocol}://${req.get("host")}`);
      const init: RequestInit & { duplex?: "half" } = {
        method: req.method, headers, signal: controller.signal,
      };
      if (req.method !== "GET" && req.method !== "HEAD") {
        init.body = Readable.toWeb(req) as ReadableStream<Uint8Array>;
        init.duplex = "half";
      }
      const request = new Request(url, init);
      const response = await router.handle(request);
      if (!response) { res.status(404).end(); return; }
      res.status(response.status);
      response.headers.forEach((value, name) => {
        if (name !== "set-cookie") res.setHeader(name, value);
      });
      const cookies = response.headers.getSetCookie();
      if (cookies.length) res.setHeader("set-cookie", cookies);
      if (req.method === "HEAD" || !response.body) {
        await response.body?.cancel();
        res.end();
      } else {
        await pipeline(Readable.fromWeb(response.body as NodeReadableStream<Uint8Array>), res, { signal: request.signal });
      }
    })().catch((error) => {
      if (!controller.signal.aborted) next(error);
    }).finally(() => {
      req.off("aborted", abort);
      res.off("close", abort);
    });
  };
}
```

import { InternalError, ValidationError } from "../core/errors.js";
import { runParallelOrdered, type ParallelOptions } from "./parallel.js";

export type Step<TIn, TOut> = (input: TIn) => Promise<TOut> | TOut;

export interface MapReduceOptions<TInput, TMapped, TReduced> extends ParallelOptions {
  map: (input: TInput, index: number) => Promise<TMapped> | TMapped;
  reduce: (inputs: TMapped[]) => Promise<TReduced> | TReduced;
}

export interface RouterOptions<TInput, TOutput> {
  routes: Record<string, Step<TInput, TOutput>>;
  router: (input: TInput) => Promise<string> | string;
}

export class Chain<TIn, TOut> {
  constructor(private readonly runHandler: (input: TIn) => Promise<TOut>) {}

  async run(input: TIn): Promise<TOut> {
    return await this.runHandler(input);
  }

  static sequential(steps: Array<Step<any, any>>): Chain<any, any> {
    return new Chain(async (input: unknown) => {
      let current = input;
      for (const step of steps) {
        current = await step(current);
      }
      return current;
    });
  }

  static parallel<T>(steps: Array<Step<T, unknown>>, options: ParallelOptions = {}): Chain<T, unknown[]> {
    return new Chain(async (input: T) => await runParallelOrdered(steps, input, options));
  }

  static mapReduce<TInput, TMapped, TReduced>(
    options: MapReduceOptions<TInput, TMapped, TReduced>
  ): Chain<TInput[], TReduced> {
    return new Chain(async (inputs: TInput[]) => {
      const mapped = await runParallelOrdered(
        inputs.map((value, index) => () => options.map(value, index)),
        undefined,
        options
      );
      return await options.reduce(mapped as TMapped[]);
    });
  }

  static router<TInput, TOutput>(options: RouterOptions<TInput, TOutput>): Chain<TInput, TOutput> {
    return new Chain(async (input: TInput) => {
      let key: string;
      try {
        key = await options.router(input);
      } catch (error) {
        throw new InternalError("Router failed to select a route", { cause: error });
      }
      const handler = Object.hasOwn(options.routes, key) ? options.routes[key] : undefined;
      if (typeof handler !== "function") {
        throw new ValidationError(`Unknown route: ${key}`, { metadata: { route: key } });
      }
      return await handler(input);
    });
  }
}

