  .docsfn-mobile-toolbar.svelte-sfp66y {
    display: block;
    padding: 0.5rem 1rem;
    border-bottom: 1px solid var(--docsfn-color-border, #e2e8f0);
    background: var(--docsfn-color-surface, #fff);
  }

  @media (min-width: 1024px) {
    /* Remove from layout flow entirely (avoids stray gap above .docsfn-container). */
    .docsfn-mobile-toolbar.svelte-sfp66y {
      display: none !important;
      height: 0;
      min-height: 0;
      margin: 0;
      padding: 0;
      border: 0;
      overflow: hidden;
    }
  }

  .docsfn-mobile-menu-btn.svelte-sfp66y {
    font: inherit;
    font-size: 0.875rem;
    padding: 0.4rem 0.75rem;
    border-radius: 0.375rem;
    border: 1px solid var(--docsfn-color-border, #e2e8f0);
    background: var(--docsfn-color-surface, #fff);
    cursor: pointer;
  }

  .docsfn-mobile-backdrop.svelte-sfp66y {
    position: fixed;
    inset: 0;
    z-index: 30;
    border: none;
    padding: 0;
    margin: 0;
    background: rgb(15 23 42 / 0.4);
    cursor: pointer;
  }

  @media (max-width: 1023px) {
    .docsfn-sidebar-col.svelte-sfp66y {
      position: fixed;
      top: 0;
      left: 0;
      bottom: 0;
      width: min(18rem, 88vw);
      z-index: 40;
      transform: translateX(-100%);
      transition: transform 0.2s ease;
      /* Drawer: no left gutter bleed; restore outer scroll (viewport may be shallow). */
      overflow-y: auto;
      box-shadow: 4px 0 24px rgb(15 23 42 / 0.12);
    }

    .docsfn-sidebar-col--open.svelte-sfp66y {
      transform: translateX(0);
