import { describe, it, expect } from "vitest";
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { buildManifest, loadDocsConfig, buildLlmsTxtArtifacts } from "@docsfn/core";
import { FsContentProvider } from "@docsfn/provider-fs";
import { buildLlmsSiteArtifacts, withSourceLinks } from "./llms.mjs";

describe("filesystem LLM consumer contract", () => {
  it.each(["default", "relative", "absolute"])("reads %s root consistently across provider and manifest", async layout => {
    const cwd = mkdtempSync(join(tmpdir(), "docs-root-"));
    try {
      const root = layout === "default" ? cwd : join(cwd, "content");
      for (const dir of ["guide", "pages", "blog", "api", "static"]) mkdirSync(join(root, dir), { recursive: true });
      writeFileSync(join(root, "guide/index.md"), "# Fixture\n\nCorrect consumer body.");
      writeFileSync(join(cwd, "docsfn.config.ts"), `export default ${JSON.stringify({ schemaVersion: 1, site: { title: "Fixture", basePath: "/docs", canonicalUrl: "https://configured.test" }, content: { root: layout === "default" ? "." : layout === "absolute" ? root : "content", docsDir: "guide", pagesDir: "pages", blogDir: "blog", apiDir: "api", assetsDir: "static" }, search: { enabled: false, scopes: [] } })}`);
      const deps = { buildManifest, loadDocsConfig, FsContentProvider, buildLlmsTxtArtifacts };
      const defaults = await buildLlmsSiteArtifacts(cwd, deps);
      expect(defaults.manifest.pages["docs:index.md"].body).toContain("Correct consumer body.");
      expect(defaults.artifacts.llmsTxt).toContain("https://configured.test/docs");
      const override = await buildLlmsSiteArtifacts(cwd, deps, { canonicalUrl: "https://override.test" });
      expect(override.canonicalUrl).toBe("https://override.test");expect(override.artifacts.llmsTxt).toContain("https://override.test/docs");
    } finally { rmSync(cwd, { recursive: true, force: true }); }
  });
  it("preserves source refs/encoded filenames/query/hash and selected-host body links", () => {
    const manifest = { pages: { x: { id: "docs:Folder/Child page.md", path: "/docs/child" } } };
    const text = "[Child](/docs/child?mode=raw#section)";
    expect(withSourceLinks(text, manifest, "mcpfn", undefined)).toContain("blob/dev/mcpfn/docs/content/docs/Folder/Child%20page.md?mode=raw#section");
    expect(withSourceLinks(text, manifest, "mcpfn", undefined, "release/v1")).toContain("blob/release%2Fv1/mcpfn/");
    expect(withSourceLinks(text, manifest, "mcpfn", "https://public.test", "release/v1")).toBe("[Child](https://public.test/docs/child?mode=raw#section)");
    expect(withSourceLinks("[Other](/docs-other)", manifest, "mcpfn", "https://public.test")).toBe("[Other](/docs-other)");
    expect(withSourceLinks("[Index](/docs) [Index](/docs?mode=raw#section)",manifest,"mcpfn","https://public.test")).toContain("https://public.test/docs?mode=raw#section");
  });
});

import { describe, expect, it, vi } from "vitest";
import { loadDocsPage } from "./page";
import type { DocsSiteSource } from "./runtime";
import { compileSvelteContent, resolveMarkdownRelativeLinks } from "@docsfn/core";
const fixture = vi.hoisted(() => ({ entry: {} as Record<string, unknown>, surface: {} as Record<string, unknown> }));
vi.mock("@docsfn/sveltekit", () => ({ resolveDocsRouteDataOrThrow: () => fixture.entry, resolveDocsPageSurface: () => fixture.surface }));
describe("docs loader contracts", () => {
 it.each(["docs", "pages"])("retains %s filename identity and lean page envelope", async collection => {
  fixture.entry = { kind: "page", route: "/docs/custom", page: { id: `${collection}:index.md`, body: "raw provider record" } };fixture.surface = {};
  const source = { manifest: { routes: {}, sidebars: {} }, searchArtifact: {} } as unknown as DocsSiteSource;
  const compiled = compileSvelteContent({ source: "[Next](next.md)", sourcePath: "index.md" });
  const data = await loadDocsPage({ slug: "custom", source, getCompiledDocsPage: vi.fn().mockResolvedValue(compiled), resolveMarkdownRelativeLinks });
  expect(data.compiled?.blocks).toContainEqual(expect.objectContaining({ html: '<a href="/docs/custom/next.md">Next</a>' }));
  expect(data.routeEntry).toEqual({ kind: "page" });expect(JSON.stringify(data)).not.toContain("raw provider record");
 });
 it.each([undefined,"","https://docs.test","https://docs.test/","https://docs.test"+"/".repeat(10000)])("preserves API records, canonical normalization and caller fallback (%s)", async canonicalUrl => {
  fixture.entry = { kind: "api", route: "/docs/api/http", api: { title: "HTTP", frontmatter: {} } };
  const sidebar = { id: "docs", items: [] };
  const source = { canonicalUrl, manifest: { sidebars: { docs: sidebar }, navigation: { topNav: [] }, versions: [] }, searchArtifact: {} } as unknown as DocsSiteSource;
  const data = await loadDocsPage({ slug: "api/http", source, getCompiledDocsPage: vi.fn(), resolveMarkdownRelativeLinks: vi.fn(), options: { fallbackSidebarId: "docs" } });
  expect(data.routeEntry).toEqual(fixture.entry);expect(data.sidebar).toBe(sidebar);
  expect(data.surface.canonicalUrl).toBe(canonicalUrl ? "https://docs.test/docs/api/http" : "/docs/api/http");
 });
});

